const express = require('express');
const app = express();

// Get configuration from environment variables with defaults
const config = {
  port: process.env.PORT || process.env.APPLICATION_PORT || process.env.SERVER_PORT || 3000,
  host: process.env.HOST || process.env.SERVER_HOST || '0.0.0.0', // Default loopback - for explicit binding use environment variable
  apiVersion: process.env.API_VERSION || 'v1',
  nodeEnv: process.env.NODE_ENV || 'development',
};

console.log(`Starting server with configuration: ${JSON.stringify({
  port: config.port,
  host: config.host,
  apiVersion: config.apiVersion,
  nodeEnv: config.nodeEnv
}, null, 2)}`);

// API endpoints with version prefix from environment
const healthPath = config.apiVersion ? `/${config.apiVersion}/health` : '/health';
const usersPath = config.apiVersion ? `/${config.apiVersion}/users` : '/users';

app.get(healthPath, (req, res) => {
  res.json({ status: 'ok' }); // Removed timestamp - no information disclosure
});

app.get(usersPath, (req, res) => {
  // In production, fetch from database or environment-based sources
  console.log('User data request received');

  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// Health endpoint should be versioned in production
app.get('/health', (req, res) => {
  res.json({ status: 'ok' });
});

// Dynamic routes can be configured via environment variables
// Example:
// const routes = process.env.ROUTES ? JSON.parse(process.env.ROUTES) : {};
// Object.keys(routes).forEach(route => {
//   app.get(route, (req, res) => res.json(routes[route]));
// });

// Bind to configured host and port
const server = app.listen(config.port, () => {
  console.log(`Server running on http://${config.host}:${config.port}`);

  // Additional logging based on environment
  if (config.nodeEnv === 'development') {
    console.log('Running in development mode');
  } else if (config.nodeEnv === 'production') {
    console.log('Running in production mode - debug logging disabled');
  }
});

module.exports = { app, server };

